class Solution {
public:
    int digitRange(int x) {
        int hi = 0, lo = 9;
        while (x) { int d = x % 10; hi = max(hi, d); lo = min(lo, d); x /= 10; }
        return hi - lo;
    }
    long long maxDigitRangeSum(vector<int>& nums) {
        int mx = 0;
        for (int x : nums) mx = max(mx, digitRange(x));
        long long ans = 0;
        for (int x : nums) if (digitRange(x) == mx) ans += x;
        return ans;
    }
};

