var maxDigitRangeSum = function(nums) {
    const rng = x => {
        const s = String(x);
        return Math.max(...s.split('').map(Number)) - Math.min(...s.split('').map(Number));
    };
    const mx = Math.max(...nums.map(rng));
    return nums.filter(x => rng(x) === mx).reduce((a, b) => a + b, 0);
